/* Independent contract fake. Compiles the SAME native wrapper on host; not ARM emulation. */
#define HOST_TEST 1
#include "native.c"
#include <assert.h>
#include <stdarg.h>
#include <stdio.h>
#include <string.h>
#include "fixture.h" /* Private actual captured rule words, generated by check.py. */

static Machine machine;
static Context context;
static Event event;
static EventData event_data;
static Cell cells[203], saved_cells[203];
static Column columns[22], saved_columns[22];
static volatile u32 logo;
static int process_calls, system_calls, stop_calls, warning_calls, used_clone;
static int focus_app, granted, selected, intro_rc, quick_rc, last_log_rc, error_logs;
static int granted_actions, denied_actions;
static word helper_return;
static void *p4=(void *)0x1010, *p5=(void *)0x2020;
static const char cmd[]="owned original intro command", quick[]="quicktranlogo";
static int rows_marker,lookup_marker;

static void original_warning(word old_context) {
    assert(old_context==1021);
    warning_calls++;
}

Binding cmu_binding(void) {
    Binding b={&machine,&context,cells,columns,(void *)rule80,(void *)rules194,
               &rows_marker,&lookup_marker,&logo,original_warning,cmd,quick};
    return b;
}
void *cmu_copy(void *d,const void *s,word n) { return memcpy(d,s,n); }
word cmu_uia_handle(void) { return 0x777; }
word cmu_focused_app(word handle) { assert(handle==0x777); return focus_app; }
int cmu_system(const char *s) {
    assert(s==cmd);assert(context.context==1021);assert(process_calls==0);
    system_calls++;return intro_rc;
}
int cmu_stop_service(const char *s) {
    assert(s==quick);assert(warning_calls==1);assert(process_calls==1);
    stop_calls++;return quick_rc;
}
int cmu_log_allowed(int level) { return level==5 || level==2; }
void cmu_log_write(int level,u32 mask,const char *module,const char *file,
                   const char *function,u32 line,const char *format,...) {
    va_list ap;va_start(ap,format);last_log_rc=va_arg(ap,int);va_end(ap);
    assert(mask==0xfff && !strcmp(module,"MMUI_SYSTEM"));
    assert(file && function && line==1 && strstr(format,"CMU_NATIVE_BYPASS"));
    if(level==2)error_logs++;
}

word cmu_stock_process(word handle,Machine *m,Event *ev,Context *current,
                        void *a4,void *a5) {
    const u32 *rule=rule80;
    process_calls++;
    assert(handle==0x1234 && ev==&event && current==&context && a4==p4 && a5==p5);
    if(m!=&machine) {
        used_clone++;
        assert(ev->app==1 && ev->payload==&event_data && ev->payload->event==1470);
        assert(m->columns_count==22 && m->rows_count==126 && m->cells_count==203);
        assert(m->rows==machine.rows && m->lookup==machine.lookup);
        for(int i=0;i<203;i++) {
            const Cell *expected=i==79 ? &cells[193] : &cells[i];
            assert(!memcmp(&m->cells[i],expected,sizeof(Cell)));
        }
        for(int i=0;i<22;i++) {
            Column expected=columns[i];
            if(i==9)expected.exit=cmu_intro_exit;
            assert(!memcmp(&m->columns[i],&expected,sizeof(Column)));
        }
        assert(m->cells[79].count==9 && m->cells[79].rules==(void *)rules194);
        /* Model first matching actual captured predicate; decision order stays OEM-owned. */
        for(int i=0;i<9;i++) {
            if(i==selected || rules194[i][0]==0) { rule=rules194[i];break; }
        }
    }
    if(granted) {
        if(rule[1])granted_actions++;
        /* NULL callback still reaches the model's stock default transition dispatch. */
        current->context=rule[5];
        m->columns[9].exit(1021);
    } else {
        if(rule[2])denied_actions++;
        assert(current->context==1021 || !used_clone);
    }
    return helper_return;
}

static void reset(void) {
    memset(&machine,0,sizeof machine);memset(cells,0,sizeof cells);
    memset(columns,0,sizeof columns);memset(&context,0,sizeof context);
    machine=(Machine){22,126,203,columns,&rows_marker,cells,&lookup_marker};
    cells[79]=(Cell){0,1,(void *)rule80};cells[193]=(Cell){0,9,(void *)rules194};
    columns[9].context=1021;columns[9].exit=original_warning;
    context.context=1021;
    event_data=(EventData){1,1470};
    event=(Event){7,1,1,&event_data,0}; /* Actual caller: app at +8, pointer at +12. */
    logo=2;focus_app=1;granted=1;selected=8;intro_rc=0;quick_rc=100;
    process_calls=system_calls=stop_calls=warning_calls=used_clone=0;
    granted_actions=denied_actions=error_logs=0;last_log_rc=-999;
    helper_return=(word)0x13572468;
    memcpy(saved_cells,cells,sizeof cells);memcpy(saved_columns,columns,sizeof columns);
}
static void invoke(void) {
    assert(cmu_native_process(0x1234,&machine,&event,&context,p4,p5)==helper_return);
    assert(!memcmp(saved_cells,cells,sizeof cells));
    assert(!memcmp(saved_columns,columns,sizeof columns));
    assert(process_calls==1);
}

int main(void) {
    for(int i=0;i<9;i++) {
        reset();selected=i;invoke();
        assert(used_clone==1 && system_calls==1 && stop_calls==1 && warning_calls==1);
        assert(logo==0 && context.context==rules194[i][5] && last_log_rc==100);
        assert(granted_actions==(rules194[i][1]!=0) && denied_actions==0);
    }
    puts("PASS nine actual OEM rule successors/flags, NULL default, one exit, exact args/return");
    for(int i=0;i<9;i++) {
        reset();selected=i;granted=0;invoke();
        assert(used_clone==1 && system_calls==1 && logo==0);
        assert(stop_calls==0 && warning_calls==0 && context.context==1021);
        assert(granted_actions==0 && denied_actions==(rules194[i][2]!=0));
    }
    puts("PASS denial preserves callback alternatives/state/return; intro disposal intentional, no quick/exit");
    for(int i=0;i<6;i++) {
        reset();granted=0;
        if(i==0)focus_app=2;
        if(i==1)logo=1;
        if(i==2)event_data.event=411;
        if(i==3)context.context=1017;
        if(i==4)machine.cells_count=202;
        if(i==5)event.payload=0;
        invoke();assert(!used_clone && !system_calls && !stop_calls && !warning_calls);
    }
    puts("PASS nofocus, unsupported mode/event/context/table remains stock before mutation");
    reset();intro_rc=7;invoke();
    assert(!used_clone && system_calls==1 && logo==2 && !stop_calls);
    assert(context.context==1010 && warning_calls==1 && error_logs==1 && last_log_rc==7);
    puts("PASS intro cleanup failure preserved/status reported and original Show path used");
    reset();quick_rc=77;invoke();
    assert(used_clone && warning_calls==1 && stop_calls==1 && error_logs==1 && last_log_rc==77);
    puts("PASS quick cleanup failure reported; normal manager result not fabricated");
    puts("HOST MODEL ONLY: no ARM execution, real manager retention/focus, startup or CMU cleanup proof");
    return 0;
}
